-- JLIKA Gym — every pending migration, concatenated in order.
--
-- GENERATED by scripts/bundle-migrations.mjs. Do not edit; edit the individual
-- files in supabase/migrations/ and regenerate.
--
-- Paste the whole thing into the Supabase SQL editor and run it once. Every
-- statement is idempotent, so running it again is harmless.
--
-- Not included: 20260905000001_profiles.sql (already applied) and
-- 20260905000012_weekly_review_cron.sql (optional; needs app.weekly_review_url
-- and app.cron_secret set on the database first).


-- ========================================================================
-- 20260905000002_program.sql
-- ========================================================================

-- JLIKA Gym — Phase 2: exercise library and the weekly program.
-- A week is a mutable draft until it is published; logged sets (Phase 3) keep
-- what was actually performed, so editing a program never rewrites history.

-- ---------------------------------------------------------------- exercises

create table if not exists public.exercises (
  id uuid primary key default gen_random_uuid(),
  -- Null = global seed row, readable by everyone. Non-null = someone's own movement.
  owner_id uuid references auth.users on delete cascade,
  slug text unique not null,
  name text not null,
  primary_muscle text not null check (primary_muscle in (
    'chest','lats','middle_back','lower_back','traps','shoulders','biceps',
    'triceps','forearms','quadriceps','hamstrings','glutes','calves',
    'abdominals','abductors','adductors','neck'
  )),
  secondary_muscles text[] not null default '{}',
  equipment text not null check (equipment in (
    'barbell','dumbbell','machine','cable','body_only','bands','kettlebells',
    'ez_curl_bar','exercise_ball','medicine_ball','foam_roll','other'
  )),
  -- Alternate spellings the paste parser matches against, so "Hamstring Curl"
  -- finds "Lying Leg Curls" without a trip through the review step.
  aliases text[] not null default '{}',
  video_url text,
  image_start_url text,
  image_end_url text,
  cues text[] not null default '{}',
  how_to text[] not null default '{}',
  common_mistake text,
  created_at timestamptz not null default now()
);

create index if not exists exercises_primary_muscle_idx on public.exercises (primary_muscle);
create index if not exists exercises_owner_idx on public.exercises (owner_id);

alter table public.exercises enable row level security;

drop policy if exists "exercises: read global or own" on public.exercises;
create policy "exercises: read global or own"
  on public.exercises for select
  using (owner_id is null or owner_id = (select auth.uid()));

drop policy if exists "exercises: insert own" on public.exercises;
create policy "exercises: insert own"
  on public.exercises for insert
  with check (owner_id = (select auth.uid()));

drop policy if exists "exercises: update own" on public.exercises;
create policy "exercises: update own"
  on public.exercises for update
  using (owner_id = (select auth.uid()))
  with check (owner_id = (select auth.uid()));

drop policy if exists "exercises: delete own" on public.exercises;
create policy "exercises: delete own"
  on public.exercises for delete
  using (owner_id = (select auth.uid()));

-- ------------------------------------------------------------ program weeks

create table if not exists public.program_weeks (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users on delete cascade,
  label text not null,
  week_start date not null,
  status text not null default 'draft' check (status in ('draft','published','archived')),
  notes text,
  created_at timestamptz not null default now(),
  unique (user_id, week_start)
);

create index if not exists program_weeks_user_start_idx
  on public.program_weeks (user_id, week_start desc);

alter table public.program_weeks enable row level security;

drop policy if exists "program_weeks: own rows" on public.program_weeks;
create policy "program_weeks: own rows"
  on public.program_weeks for all
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

-- ------------------------------------------------------------- program days

create table if not exists public.program_days (
  id uuid primary key default gen_random_uuid(),
  week_id uuid not null references public.program_weeks on delete cascade,
  day_index int not null check (day_index between 0 and 6),   -- 0 = Monday
  name text not null,
  focus_note text,
  is_rest boolean not null default false,
  unique (week_id, day_index)
);

alter table public.program_days enable row level security;

-- Child tables check ownership through the parent rather than carrying a
-- duplicate user_id that could drift out of sync.
drop policy if exists "program_days: through week" on public.program_days;
create policy "program_days: through week"
  on public.program_days for all
  using (exists (
    select 1 from public.program_weeks w
    where w.id = week_id and w.user_id = (select auth.uid())
  ))
  with check (exists (
    select 1 from public.program_weeks w
    where w.id = week_id and w.user_id = (select auth.uid())
  ));

-- -------------------------------------------------------- program exercises

create table if not exists public.program_exercises (
  id uuid primary key default gen_random_uuid(),
  day_id uuid not null references public.program_days on delete cascade,
  exercise_id uuid not null references public.exercises,
  position int not null,
  target_sets int not null check (target_sets between 1 and 20),
  rep_min int check (rep_min > 0),
  rep_max int check (rep_max > 0),
  per_side boolean not null default false,
  note text,
  constraint program_exercises_rep_range check (rep_max is null or rep_min is null or rep_max >= rep_min)
);

create index if not exists program_exercises_day_position_idx
  on public.program_exercises (day_id, position);

alter table public.program_exercises enable row level security;

drop policy if exists "program_exercises: through day" on public.program_exercises;
create policy "program_exercises: through day"
  on public.program_exercises for all
  using (exists (
    select 1 from public.program_days d
    join public.program_weeks w on w.id = d.week_id
    where d.id = day_id and w.user_id = (select auth.uid())
  ))
  with check (exists (
    select 1 from public.program_days d
    join public.program_weeks w on w.id = d.week_id
    where d.id = day_id and w.user_id = (select auth.uid())
  ));


-- ========================================================================
-- 20260905000003_seed_exercises.sql
-- ========================================================================

-- JLIKA Gym — Phase 2 seed: the global exercise library.
--
-- Generated from free-exercise-db (https://github.com/yuhonas/free-exercise-db),
-- which is public domain — the same source the program PDF credits. Photos are
-- hotlinked to raw.githubusercontent.com for now; mirror them into Supabase
-- Storage before this goes anywhere near production traffic.
--
-- owner_id stays null so every account can read these but nobody can edit them.
-- Re-runnable: conflicts on slug refresh the row instead of erroring.

insert into public.exercises
  (slug, name, primary_muscle, secondary_muscles, equipment, aliases,
   image_start_url, image_end_url, how_to, cues, common_mistake)
values
  ('incline-dumbbell-press', 'Incline Dumbbell Press', 'chest', array['shoulders','triceps']::text[], 'dumbbell', array['Incline DB Press']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Dumbbell_Press/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Dumbbell_Press/1.jpg', array['Lie back on an incline bench with a dumbbell in each hand atop your thighs. The palms of your hands will be facing each other.','Then, using your thighs to help push the dumbbells up, lift the dumbbells one at a time so that you can hold them at shoulder width.','Once you have the dumbbells raised to shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.','Be sure to keep full control of the dumbbells at all times. Then breathe out and push the dumbbells up with your chest.','Lock your arms at the top, hold for a second, and then start slowly lowering the weight. Tip Ideally, lowering the weights should take about twice as long as raising them.','Repeat the movement for the prescribed amount of repetitions.']::text[], '{}'::text[], null),
  ('wide-grip-lat-pulldown', 'Wide-Grip Lat Pulldown', 'lats', array['biceps','middle_back','shoulders']::text[], 'cable', array['Wide Grip Lat Pulldown','Lat Pulldown']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wide-Grip_Lat_Pulldown/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wide-Grip_Lat_Pulldown/1.jpg', array['Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.','Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.','As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.','As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the bar; therefore do not try to pull down the bar using the forearms.','After a second at the contracted position squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.','Repeat this motion for the prescribed amount of repetitions.']::text[], '{}'::text[], null),
  ('leverage-chest-press', 'Leverage Chest Press', 'chest', array['shoulders','triceps']::text[], 'machine', array['Machine Chest Press','Chest Press Machine']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leverage_Chest_Press/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leverage_Chest_Press/1.jpg', array['Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the bottom or middle of the pectorals at the beginning of the motion.','Your chest and head should be up and your shoulder blades retracted. This will be your starting position.','Press the handles forward by extending through the elbow.','After a brief pause at the top, return the weight just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete.']::text[], '{}'::text[], null),
  ('seated-cable-rows', 'Seated Cable Rows', 'middle_back', array['biceps','lats','shoulders']::text[], 'cable', array['Seated Cable Row','Cable Row']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Cable_Rows/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Cable_Rows/1.jpg', array['For this exercise you will need access to a low pulley row machine with a V-bar. Note: The V-bar will enable you to have a neutral grip where the palms of your hands face each other. To get into the starting position, first sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked.','Lean over as you keep the natural alignment of your back and grab the V-bar handles.','With your arms extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You should be feeling a nice stretch on your lats as you hold the bar in front of you. This is the starting position of the exercise.','Keeping the torso stationary, pull the handles back towards your torso while keeping the arms close to it until you touch the abdominals. Breathe out as you perform that movement. At that point you should be squeezing your back muscles hard. Hold that contraction for a second and slowly go back to the original position while breathing in.','Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], null),
  ('side-lateral-raise', 'Side Lateral Raise', 'shoulders', '{}'::text[], 'dumbbell', array['Dumbbell Lateral Raise','DB Lateral Raise','Lateral Raise']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Lateral_Raise/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Lateral_Raise/1.jpg', array['Pick a couple of dumbbells and stand with a straight torso and the dumbbells by your side at arms length with the palms of the hand facing you. This will be your starting position.','While maintaining the torso in a stationary position (no swinging), lift the dumbbells to your side with a slight bend on the elbow and the hands slightly tilted forward as if pouring water in a glass. Continue to go up until you arms are parallel to the floor. Exhale as you execute this movement and pause for a second at the top.','Lower the dumbbells back down slowly to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], null),
  ('triceps-pushdown', 'Triceps Pushdown', 'triceps', '{}'::text[], 'cable', array['Cable Tricep Pushdown','Tricep Pushdown','Rope Pushdown']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Triceps_Pushdown/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Triceps_Pushdown/1.jpg', array['Attach a straight or angled bar to a high pulley and grab with an overhand grip (palms facing down) at shoulder width.','Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the bar. This is your starting position.','Using the triceps, bring the bar down until it touches the front of your thighs and the arms are fully extended perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.','After a second hold at the contracted position, bring the bar slowly up to the starting point. Breathe in as you perform this step.','Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], null),
  ('ez-bar-curl', 'EZ-Bar Curl', 'biceps', '{}'::text[], 'ez_curl_bar', array['EZ Bar Curl','Barbell Curl EZ']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/EZ-Bar_Curl/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/EZ-Bar_Curl/1.jpg', array['Stand up straight while holding an EZ curl bar at the wide outer handle. The palms of your hands should be facing forward and slightly tilted inward due to the shape of the bar. Keep your elbows close to your torso. This will be your starting position.','Now, while keeping your upper arms stationary, exhale and curl the weights forward while contracting the biceps. Focus on only moving your forearms.','Continue to raise the weight until your biceps are fully contracted and the bar is at shoulder level. Hold the top contracted position for a moment and squeeze the biceps.','Then inhale and slowly lower the bar back to the starting position.','Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], null),
  ('leg-press', 'Leg Press', 'quadriceps', array['calves','glutes','hamstrings']::text[], 'machine', '{}'::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leg_Press/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leg_Press/1.jpg', array['Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a medium (shoulder width) foot stance. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).','Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you. Tip: Make sure that you do not lock your knees. Your torso and the legs should make a perfect 90-degree angle. This will be your starting position.','As you inhale, slowly lower the platform until your upper and lower legs make a 90-degree angle.','Pushing mainly with the heels of your feet and using the quadriceps go back to the starting position as you exhale.','Repeat for the recommended amount of repetitions and ensure to lock the safety pins properly once you are done. You do not want that platform falling on you fully loaded.']::text[], '{}'::text[], null),
  ('romanian-deadlift', 'Romanian Deadlift', 'hamstrings', array['calves','glutes','lower_back']::text[], 'barbell', array['RDL']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Romanian_Deadlift/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Romanian_Deadlift/1.jpg', array['Put a barbell in front of you on the ground and grab it using a pronated (palms facing down) grip that a little wider than shoulder width. Tip: Depending on the weight used, you may need wrist wraps to perform the exercise and also a raised platform in order to allow for better range of motion.','Bend the knees slightly and keep the shins vertical, hips back and back straight. This will be your starting position.','Keeping your back and arms completely straight at all times, use your hips to lift the bar as you exhale. Tip: The movement should not be fast but steady and under control.','Once you are standing completely straight up, lower the bar by pushing the hips back, only slightly bending the knees, unlike when squatting. Tip: Take a deep breath at the start of the movement and keep your chest up. Hold your breath as you lower and exhale as you complete the movement.','Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], null),
  ('barbell-walking-lunge', 'Barbell Walking Lunge', 'quadriceps', array['calves','glutes','hamstrings']::text[], 'barbell', array['Walking Lunges','Walking Lunge']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Walking_Lunge/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Walking_Lunge/1.jpg', array['Begin standing with your feet shoulder width apart and a barbell across your upper back.','Step forward with one leg, flexing the knees to drop your hips. Descend until your rear knee nearly touches the ground. Your posture should remain upright, and your front knee should stay above the front foot.','Drive through the heel of your lead foot and extend both knees to raise yourself back up.','Step forward with your rear foot, repeating the lunge on the opposite leg.']::text[], '{}'::text[], null),
  ('leg-extensions', 'Leg Extensions', 'quadriceps', '{}'::text[], 'machine', array['Leg Extension']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leg_Extensions/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leg_Extensions/1.jpg', array['For this exercise you will need to use a leg extension machine. First choose your weight and sit on the machine with your legs under the pad (feet pointed forward) and the hands holding the side bars. This will be your starting position. Tip: You will need to adjust the pad so that it falls on top of your lower leg (just above your feet). Also, make sure that your legs form a 90-degree angle between the lower and upper leg. If the angle is less than 90-degrees then that means the knee is over the toes which in turn creates undue stress at the knee joint. If the machine is designed that way, either look for another machine or just make sure that when you start executing the exercise you stop going down once you hit the 90-degree angle.','Using your quadriceps, extend your legs to the maximum as you exhale. Ensure that the rest of the body remains stationary on the seat. Pause a second on the contracted position.','Slowly lower the weight back to the original position as you inhale, ensuring that you do not go past the 90-degree angle limit.','Repeat for the recommended amount of times.']::text[], '{}'::text[], null),
  ('lying-leg-curls', 'Lying Leg Curls', 'hamstrings', '{}'::text[], 'machine', array['Hamstring Curl','Lying Hamstring Curl','Leg Curl']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Leg_Curls/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Leg_Curls/1.jpg', array['Adjust the machine lever to fit your height and lie face down on the leg curl machine with the pad of the lever on the back of your legs (just a few inches under the calves). Tip: Preferably use a leg curl machine that is angled as opposed to flat since an angled position is more favorable for hamstrings recruitment.','Keeping the torso flat on the bench, ensure your legs are fully stretched and grab the side handles of the machine. Position your toes straight (or you can also use any of the other two stances described on the foot positioning section). This will be your starting position.','As you exhale, curl your legs up as far as possible without lifting the upper legs from the pad. Once you hit the fully contracted position, hold it for a second.','As you inhale, bring the legs back to the initial position. Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], null),
  ('standing-calf-raises', 'Standing Calf Raises', 'calves', '{}'::text[], 'machine', array['Standing Calf Raise']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Calf_Raises/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Calf_Raises/1.jpg', array['Adjust the padded lever of the calf raise machine to fit your height.','Place your shoulders under the pads provided and position your toes facing forward (or using any of the two other positions described at the beginning of the chapter). The balls of your feet should be secured on top of the calf block with the heels extending off it. Push the lever up by extending your hips and knees until your torso is standing erect. The knees should be kept with a slight bend; never locked. Toes should be facing forward, outwards or inwards as described at the beginning of the chapter. This will be your starting position.','Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.','Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.','Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], null),
  ('hanging-leg-raise', 'Hanging Leg Raise', 'abdominals', '{}'::text[], 'body_only', array['Hanging Knee Raises','Hanging Knee Raise']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hanging_Leg_Raise/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hanging_Leg_Raise/1.jpg', array['Hang from a chin-up bar with both arms extended at arms length in top of you using either a wide grip or a medium grip. The legs should be straight down with the pelvis rolled slightly backwards. This will be your starting position.','Raise your legs until the torso makes a 90-degree angle with the legs. Exhale as you perform this movement and hold the contraction for a second or so.','Go back slowly to the starting position as you breathe in.','Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], null),
  ('dumbbell-bench-press', 'Dumbbell Bench Press', 'chest', array['shoulders','triceps']::text[], 'dumbbell', array['Flat Dumbbell Press','Flat DB Press']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Bench_Press/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Bench_Press/1.jpg', array['Lie down on a flat bench with a dumbbell in each hand resting on top of your thighs. The palms of your hands will be facing each other.','Then, using your thighs to help raise the dumbbells up, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.','Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. The dumbbells should be just to the sides of your chest, with your upper arm and forearm creating a 90 degree angle. Be sure to maintain full control of the dumbbells at all times. This will be your starting position.','Then, as you breathe out, use your chest to push the dumbbells up. Lock your arms at the top of the lift and squeeze your chest, hold for a second and then begin coming down slowly. Tip: Ideally, lowering the weight should take about twice as long as raising it.','Repeat the movement for the prescribed amount of repetitions of your training program.']::text[], '{}'::text[], null),
  ('close-grip-front-lat-pulldown', 'Close-Grip Front Lat Pulldown', 'lats', array['biceps','middle_back','shoulders']::text[], 'cable', array['Close Grip Lat Pulldown']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_Front_Lat_Pulldown/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_Front_Lat_Pulldown/1.jpg', array['Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.','Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.','As you have both arms extended in front of you - while holding the bar at the chosen grip width - bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.','As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary (only the arms should move). The forearms should do no other work except for holding the bar; therefore do not try to pull the bar down using the forearms.','After a second in the contracted position, while squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.','6. Repeat this motion for the prescribed amount of repetitions.']::text[], '{}'::text[], null),
  ('leverage-iso-row', 'Leverage Iso Row', 'lats', array['biceps','middle_back']::text[], 'machine', array['Chest Supported Row','Machine Row']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leverage_Iso_Row/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leverage_Iso_Row/1.jpg', array['Load an appropriate weight onto the pins and adjust the seat height so that the handles are at chest level. Grasp the handles with either a neutral or pronated grip. This will be your starting position.','Pull the handles towards your torso, retracting your shoulder blades as you flex the elbow.','Pause at the bottom of the motion, and then slowly return the handles to the starting position. For multiple repetitions, avoid completely returning the weight to the stops to keep tension on the muscles being worked.']::text[], '{}'::text[], null),
  ('machine-shoulder-military-press', 'Machine Shoulder (Military) Press', 'shoulders', array['triceps']::text[], 'machine', array['Machine Shoulder Press','Shoulder Press Machine']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Machine_Shoulder_Military_Press/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Machine_Shoulder_Military_Press/1.jpg', array['Sit down on the Shoulder Press Machine and select the weight.','Grab the handles to your sides as you keep the elbows bent and in line with your torso. This will be your starting position.','Now lift the handles as you exhale and you extend the arms fully. At the top of the position make sure that you hold the contraction for a second.','Lower the handles slowly back to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], null),
  ('cable-seated-lateral-raise', 'Cable Seated Lateral Raise', 'shoulders', array['middle_back','traps']::text[], 'cable', array['Cable Lateral Raise']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Seated_Lateral_Raise/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Seated_Lateral_Raise/1.jpg', array['Stand in the middle of two low pulleys that are opposite to each other and place a flat bench right behind you (in perpendicular fashion to you; the narrow edge of the bench should be the one behind you). Select the weight to be used on each pulley.','Now sit at the edge of the flat bench behind you with your feet placed in front of your knees.','Bend forward while keeping your back flat and rest your torso on the thighs.','Have someone give you the single handles attached to the pulleys. Grasp the left pulley with the right hand and the right pulley with the left after you select your weight. The pulleys should run under your knees and your arms will be extended with palms facing each other and a slight bend at the elbows. This will be the starting position.','While keeping the arms stationary, raise the upper arms to the sides until they are parallel to the floor and at shoulder height. Exhale during the execution of this movement and hold the contraction for a second.','Slowly lower your arms to the starting position as you inhale.']::text[], '{}'::text[], null),
  ('cable-rope-overhead-triceps-extension', 'Cable Rope Overhead Triceps Extension', 'triceps', '{}'::text[], 'cable', array['Overhead Cable Tricep Extension','Overhead Tricep Extension']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Rope_Overhead_Triceps_Extension/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Rope_Overhead_Triceps_Extension/1.jpg', array['Attach a rope to the bottom pulley of the pulley machine.','Grasping the rope with both hands, extend your arms with your hands directly above your head using a neutral grip (palms facing each other). Your elbows should be in close to your head and the arms should be perpendicular to the floor with the knuckles aimed at the ceiling. This will be your starting position.','Slowly lower the rope behind your head as you hold the upper arms stationary. Inhale as you perform this movement and pause when your triceps are fully stretched.','Return to the starting position by flexing your triceps as you breathe out.','Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], null),
  ('incline-dumbbell-curl', 'Incline Dumbbell Curl', 'biceps', '{}'::text[], 'dumbbell', array['Incline DB Curl']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Dumbbell_Curl/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Dumbbell_Curl/1.jpg', array['Sit back on an incline bench with a dumbbell in each hand held at arms length. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position.','While holding the upper arm stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second.','Slowly begin to bring the dumbbells back to starting position as your breathe in.','Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], null),
  ('hack-squat', 'Hack Squat', 'quadriceps', array['calves','glutes','hamstrings']::text[], 'machine', array['Machine Hack Squat']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hack_Squat/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hack_Squat/1.jpg', array['Place the back of your torso against the back pad of the machine and hook your shoulders under the shoulder pads provided.','Position your legs in the platform using a shoulder width medium stance with the toes slightly pointed out. Tip: Keep your head up at all times and also maintain the back on the pad at all times.','Place your arms on the side handles of the machine and disengage the safety bars (which on most designs is done by moving the side handles from a facing front position to a diagonal position).','Now straighten your legs without locking the knees. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).','Begin to slowly lower the unit by bending the knees as you maintain a straight posture with the head up (back on the pad at all times). Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.','Begin to raise the unit as you exhale by pushing the floor with mainly with the heel of your foot as you straighten the legs again and go back to the starting position.']::text[], '{}'::text[], null),
  ('seated-leg-curl', 'Seated Leg Curl', 'hamstrings', '{}'::text[], 'machine', array['Seated Hamstring Curl']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Leg_Curl/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Leg_Curl/1.jpg', array['Adjust the machine lever to fit your height and sit on the machine with your back against the back support pad.','Place the back of lower leg on top of padded lever (just a few inches under the calves) and secure the lap pad against your thighs, just above the knees. Then grasp the side handles on the machine as you point your toes straight (or you can also use any of the other two stances) and ensure that the legs are fully straight right in front of you. This will be your starting position.','As you exhale, pull the machine lever as far as possible to the back of your thighs by flexing at the knees. Keep your torso stationary at all times. Hold the contracted position for a second.','Slowly return to the starting position as you breathe in.','Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], null),
  ('seated-calf-raise', 'Seated Calf Raise', 'calves', '{}'::text[], 'machine', '{}'::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Calf_Raise/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Calf_Raise/1.jpg', array['Sit on the machine and place your toes on the lower portion of the platform provided with the heels extending off. Choose the toe positioning of your choice (forward, in, or out) as per the beginning of this chapter.','Place your lower thighs under the lever pad, which will need to be adjusted according to the height of your thighs. Now place your hands on top of the lever pad in order to prevent it from slipping forward.','Lift the lever slightly by pushing your heels up and release the safety bar. This will be your starting position.','Slowly lower your heels by bending at the ankles until the calves are fully stretched. Inhale as you perform this movement.','Raise the heels by extending the ankles as high as possible as you contract the calves and breathe out. Hold the top contraction for a second.','Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], null),
  ('cable-crunch', 'Cable Crunch', 'abdominals', '{}'::text[], 'cable', array['Rope Crunch']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Crunch/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Crunch/1.jpg', array['Kneel below a high pulley that contains a rope attachment.','Grasp cable rope attachment and lower the rope until your hands are placed next to your face.','Flex your hips slightly and allow the weight to hyperextend the lower back. This will be your starting position.','With the hips stationary, flex the waist as you contract the abs so that the elbows travel towards the middle of the thighs. Exhale as you perform this portion of the movement and hold the contraction for a second.','Slowly return to the starting position as you inhale. Tip: Make sure that you keep constant tension on the abs throughout the movement. Also, do not choose a weight so heavy that the lower back handles the brunt of the work.','Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], null),
  ('barbell-bench-press-medium-grip', 'Barbell Bench Press - Medium Grip', 'chest', array['shoulders','triceps']::text[], 'barbell', array['Bench Press','Barbell Bench Press']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Bench_Press_-_Medium_Grip/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Bench_Press_-_Medium_Grip/1.jpg', array['Lie back on a flat bench. Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.','From the starting position, breathe in and begin coming down slowly until the bar touches your middle chest.','After a brief pause, push the bar back to the starting position as you breathe out. Focus on pushing the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position at the top of the motion, hold for a second and then start coming down slowly again. Tip: Ideally, lowering the weight should take about twice as long as raising it.','Repeat the movement for the prescribed amount of repetitions.','When you are done, place the bar back in the rack.']::text[], '{}'::text[], null),
  ('barbell-squat', 'Barbell Squat', 'quadriceps', array['calves','glutes','hamstrings','lower_back']::text[], 'barbell', array['Back Squat','Squat']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Squat/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Squat/1.jpg', array['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack to just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.','Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.','Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section).','Begin to slowly lower the bar by bending the knees and hips as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees. Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.','Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position.','Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], null),
  ('barbell-deadlift', 'Barbell Deadlift', 'lower_back', array['calves','forearms','glutes','hamstrings','lats','middle_back','quadriceps','traps']::text[], 'barbell', array['Deadlift']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Deadlift/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Deadlift/1.jpg', array['Stand in front of a loaded barbell.','While keeping the back as straight as possible, bend your knees, bend forward and grasp the bar using a medium (shoulder width) overhand grip. This will be the starting position of the exercise. Tip: If it is difficult to hold on to the bar with this grip, alternate your grip or use wrist straps.','While holding the bar, start the lift by pushing with your legs while simultaneously getting your torso to the upright position as you breathe out. In the upright position, stick your chest out and contract the back by bringing the shoulder blades back. Think of how the soldiers in the military look when they are in standing in attention.','Go back to the starting position by bending at the knees while simultaneously leaning the torso forward at the waist while keeping the back straight. When the weights on the bar touch the floor you are back at the starting position and ready to perform another repetition.','Perform the amount of repetitions prescribed in the program.']::text[], '{}'::text[], null),
  ('front-barbell-squat', 'Front Barbell Squat', 'quadriceps', array['calves','glutes','hamstrings']::text[], 'barbell', array['Front Squat']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Barbell_Squat/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Barbell_Squat/1.jpg', array['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, bring your arms up under the bar while keeping the elbows high and the upper arm slightly above parallel to the floor. Rest the bar on top of the deltoids and cross your arms while grasping the bar for total control.','Lift the bar off the rack by first pushing with your legs and at the same time straightening your torso.','Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).','Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.','Begin to raise the bar as you exhale by pushing the floor mainly with the middle of your foot as you straighten the legs again and go back to the starting position.','Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], null),
  ('pullups', 'Pullups', 'lats', array['biceps','middle_back']::text[], 'body_only', array['Pull Up','Pull-Ups','Pullup']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pullups/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pullups/1.jpg', array['Grab the pull-up bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.','As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.','Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.','After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.','Repeat this motion for the prescribed amount of repetitions.']::text[], '{}'::text[], null),
  ('chin-up', 'Chin-Up', 'lats', array['biceps','forearms','middle_back']::text[], 'body_only', array['Chin Up','Chinup']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chin-Up/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chin-Up/1.jpg', array['Grab the pull-up bar with the palms facing your torso and a grip closer than the shoulder width.','As you have both arms extended in front of you holding the bar at the chosen grip width, keep your torso as straight as possible while creating a curvature on your lower back and sticking your chest out. This is your starting position. Tip: Keeping the torso as straight as possible maximizes biceps stimulation while minimizing back involvement.','As you breathe out, pull your torso up until your head is around the level of the pull-up bar. Concentrate on using the biceps muscles in order to perform the movement. Keep the elbows close to your body. Tip: The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.','After a second of squeezing the biceps in the contracted position, slowly lower your torso back to the starting position; when your arms are fully extended. Breathe in as you perform this portion of the movement.','Repeat this motion for the prescribed amount of repetitions.']::text[], '{}'::text[], null),
  ('dips-triceps-version', 'Dips - Triceps Version', 'triceps', array['chest','shoulders']::text[], 'body_only', array['Tricep Dips','Dips']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dips_-_Triceps_Version/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dips_-_Triceps_Version/1.jpg', array['To get into the starting position, hold your body at arm''s length with your arms nearly locked above the bars.','Now, inhale and slowly lower yourself downward. Your torso should remain upright and your elbows should stay close to your body. This helps to better focus on tricep involvement. Lower yourself until there is a 90 degree angle formed between the upper arm and forearm.','Then, exhale and push your torso back up using your triceps to bring your body back to the starting position.','Repeat the movement for the prescribed amount of repetitions.']::text[], '{}'::text[], null),
  ('pushups', 'Pushups', 'chest', array['shoulders','triceps']::text[], 'body_only', array['Push Up','Push-Ups','Push Ups']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pushups/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pushups/1.jpg', array['Lie on the floor face down and place your hands about 36 inches apart while holding your torso up at arms length.','Next, lower yourself downward until your chest almost touches the floor as you inhale.','Now breathe out and press your upper body back up to the starting position while squeezing your chest.','After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed.']::text[], '{}'::text[], null),
  ('bent-over-barbell-row', 'Bent Over Barbell Row', 'middle_back', array['biceps','lats','shoulders']::text[], 'barbell', array['Barbell Row','Bent Over Row']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Barbell_Row/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Barbell_Row/1.jpg', array['Holding a barbell with a pronated grip (palms facing down), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.','Now, while keeping the torso stationary, breathe out and lift the barbell to you. Keep the elbows close to the body and only use the forearms to hold the weight. At the top contracted position, squeeze the back muscles and hold for a brief pause.','Then inhale and slowly lower the barbell back to the starting position.','Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], null),
  ('one-arm-dumbbell-row', 'One-Arm Dumbbell Row', 'middle_back', array['biceps','lats','shoulders']::text[], 'dumbbell', array['Dumbbell Row','DB Row','Single Arm Row']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Dumbbell_Row/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Dumbbell_Row/1.jpg', array['Choose a flat bench and place a dumbbell on each side of it.','Place the right leg on top of the end of the bench, bend your torso forward from the waist until your upper body is parallel to the floor, and place your right hand on the other end of the bench for support.','Use the left hand to pick up the dumbbell on the floor and hold the weight while keeping your lower back straight. The palm of the hand should be facing your torso. This will be your starting position.','Pull the resistance straight up to the side of your chest, keeping your upper arm close to your side and keeping the torso stationary. Breathe out as you perform this step. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. Also, make sure that the force is performed with the back muscles and not the arms. Finally, the upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the dumbbell; therefore do not try to pull the dumbbell up using the forearms.','Lower the resistance straight down to the starting position. Breathe in as you perform this step.','Repeat the movement for the specified amount of repetitions.']::text[], '{}'::text[], null),
  ('standing-military-press', 'Standing Military Press', 'shoulders', array['triceps']::text[], 'barbell', array['Overhead Press','Military Press','OHP']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Military_Press/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Military_Press/1.jpg', array['Start by placing a barbell that is about chest high on a squat rack. Once you have selected the weights, grab the barbell using a pronated (palms facing forward) grip. Make sure to grip the bar wider than shoulder width apart from each other.','Slightly bend the knees and place the barbell on your collar bone. Lift the barbell up keeping it lying on your chest. Take a step back and position your feet shoulder width apart from each other.','Once you pick up the barbell with the correct grip length, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position.','Lower the bar down to the collarbone slowly as you inhale.','Lift the bar back up to the starting position as you exhale.','Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], null),
  ('arnold-dumbbell-press', 'Arnold Dumbbell Press', 'shoulders', array['triceps']::text[], 'dumbbell', array['Arnold Press']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Arnold_Dumbbell_Press/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Arnold_Dumbbell_Press/1.jpg', array['Sit on an exercise bench with back support and hold two dumbbells in front of you at about upper chest level with your palms facing your body and your elbows bent. Tip: Your arms should be next to your torso. The starting position should look like the contracted portion of a dumbbell curl.','Now to perform the movement, raise the dumbbells as you rotate the palms of your hands until they are facing forward.','Continue lifting the dumbbells until your arms are extended above you in straight arm position. Breathe out as you perform this portion of the movement.','After a second pause at the top, begin to lower the dumbbells to the original position by rotating the palms of your hands towards you. Tip: The left arm will be rotated in a counter clockwise manner while the right one will be rotated clockwise. Breathe in as you perform this portion of the movement.','Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], null),
  ('dumbbell-shoulder-press', 'Dumbbell Shoulder Press', 'shoulders', array['triceps']::text[], 'dumbbell', array['DB Shoulder Press','Seated Dumbbell Press']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Shoulder_Press/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Shoulder_Press/1.jpg', array['While holding a dumbbell in each hand, sit on a military press bench or utility bench that has back support. Place the dumbbells upright on top of your thighs.','Now raise the dumbbells to shoulder height one at a time using your thighs to help propel them up into position.','Make sure to rotate your wrists so that the palms of your hands are facing forward. This is your starting position.','Now, exhale and push the dumbbells upward until they touch at the top.','Then, after a brief pause at the top contracted position, slowly lower the weights back down to the starting position while inhaling.','Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], null),
  ('face-pull', 'Face Pull', 'shoulders', array['middle_back']::text[], 'cable', array['Cable Face Pull']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Face_Pull/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Face_Pull/1.jpg', array['Facing a high pulley with a rope or dual handles attached, pull the weight directly towards your face, separating your hands as you do so. Keep your upper arms parallel to the ground.']::text[], '{}'::text[], null),
  ('upright-barbell-row', 'Upright Barbell Row', 'shoulders', array['traps']::text[], 'barbell', array['Upright Row']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Upright_Barbell_Row/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Upright_Barbell_Row/1.jpg', array['Grasp a barbell with an overhand grip that is slightly less than shoulder width. The bar should be resting on the top of your thighs with your arms extended and a slight bend in your elbows. Your back should also be straight. This will be your starting position.','Now exhale and use the sides of your shoulders to lift the bar, raising your elbows up and to the side. Keep the bar close to your body as you raise it. Continue to lift the bar until it nearly touches your chin. Tip: Your elbows should drive the motion, and should always be higher than your forearms. Remember to keep your torso stationary and pause for a second at the top of the movement.','Lower the bar back down slowly to the starting position. Inhale as you perform this portion of the movement.','Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], null),
  ('barbell-curl', 'Barbell Curl', 'biceps', array['forearms']::text[], 'barbell', array['BB Curl']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Curl/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Curl/1.jpg', array['Stand up with your torso upright while holding a barbell at a shoulder-width grip. The palm of your hands should be facing forward and the elbows should be close to the torso. This will be your starting position.','While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move.','Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.','Slowly begin to bring the bar back to starting position as your breathe in.','Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], null),
  ('dumbbell-bicep-curl', 'Dumbbell Bicep Curl', 'biceps', array['forearms']::text[], 'dumbbell', array['Dumbbell Curl','DB Curl','Bicep Curl']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Bicep_Curl/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Bicep_Curl/1.jpg', array['Stand up straight with a dumbbell in each hand at arm''s length. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position.','Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps.','Then, inhale and slowly begin to lower the dumbbells back to the starting position.','Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], null),
  ('hammer-curls', 'Hammer Curls', 'biceps', '{}'::text[], 'dumbbell', array['Hammer Curl']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hammer_Curls/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hammer_Curls/1.jpg', array['Stand up with your torso upright and a dumbbell on each hand being held at arms length. The elbows should be close to the torso.','The palms of the hands should be facing your torso. This will be your starting position.','Now, while holding your upper arm stationary, exhale and curl the weight forward while contracting the biceps. Continue to raise the weight until the biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a brief moment as you squeeze the biceps. Tip: Focus on keeping the elbow stationary and only moving your forearm.','After the brief pause, inhale and slowly begin the lower the dumbbells back down to the starting position.','Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], null),
  ('preacher-curl', 'Preacher Curl', 'biceps', '{}'::text[], 'barbell', '{}'::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Preacher_Curl/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Preacher_Curl/1.jpg', array['To perform this movement you will need a preacher bench and an E-Z bar. Grab the E-Z curl bar at the close inner handle (either have someone hand you the bar which is preferable or grab the bar from the front bar rest provided by most preacher benches). The palm of your hands should be facing forward and they should be slightly tilted inwards due to the shape of the bar.','With the upper arms positioned against the preacher bench pad and the chest against it, hold the E-Z Curl Bar at shoulder length. This will be your starting position.','As you breathe in, slowly lower the bar until your upper arm is extended and the biceps is fully stretched.','As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the bar is at shoulder height. Squeeze the biceps hard and hold this position for a second.','Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], null),
  ('lying-triceps-press', 'Lying Triceps Press', 'triceps', '{}'::text[], 'ez_curl_bar', array['Skullcrusher','Skull Crusher','Lying Tricep Extension']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Triceps_Press/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Triceps_Press/1.jpg', array['Lie on a flat bench with either an e-z bar (my preference) or a straight bar placed on the floor behind your head and your feet on the floor.','Grab the bar behind you, using a medium overhand (pronated) grip, and raise the bar in front of you at arms length. Tip: The arms should be perpendicular to the torso and the floor. The elbows should be tucked in. This is the starting position.','As you breathe in, slowly lower the weight until the bar lightly touches your forehead while keeping the upper arms and elbows stationary.','At that point, use the triceps to bring the weight back up to the starting position as you breathe out.','Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], null),
  ('cable-crossover', 'Cable Crossover', 'chest', array['shoulders']::text[], 'cable', array['Cable Fly','Cable Flye']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Crossover/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Crossover/1.jpg', array['To get yourself into the starting position, place the pulleys on a high position (above your head), select the resistance to be used and hold the pulleys in each hand.','Step forward in front of an imaginary straight line between both pulleys while pulling your arms together in front of you. Your torso should have a small forward bend from the waist. This will be your starting position.','With a slight bend on your elbows in order to prevent stress at the biceps tendon, extend your arms to the side (straight out at both sides) in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms and torso should remain stationary; the movement should only occur at the shoulder joint.','Return your arms back to the starting position as you breathe out. Make sure to use the same arc of motion used to lower the weights.','Hold for a second at the starting position and repeat the movement for the prescribed amount of repetitions.']::text[], '{}'::text[], null),
  ('dumbbell-flyes', 'Dumbbell Flyes', 'chest', '{}'::text[], 'dumbbell', array['Dumbbell Fly','DB Fly']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Flyes/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Flyes/1.jpg', array['Lie down on a flat bench with a dumbbell on each hand resting on top of your thighs. The palms of your hand will be facing each other.','Then using your thighs to help raise the dumbbells, lift the dumbbells one at a time so you can hold them in front of you at shoulder width with the palms of your hands facing each other. Raise the dumbbells up like you''re pressing them, but stop and hold just before you lock out. This will be your starting position.','With a slight bend on your elbows in order to prevent stress at the biceps tendon, lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms should remain stationary; the movement should only occur at the shoulder joint.','Return your arms back to the starting position as you squeeze your chest muscles and breathe out. Tip: Make sure to use the same arc of motion used to lower the weights.','Hold for a second at the contracted position and repeat the movement for the prescribed amount of repetitions.']::text[], '{}'::text[], null),
  ('butterfly', 'Butterfly', 'chest', '{}'::text[], 'machine', array['Pec Deck','Machine Fly','Pec Dec']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Butterfly/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Butterfly/1.jpg', array['Sit on the machine with your back flat on the pad.','Take hold of the handles. Tip: Your upper arms should be positioned parallel to the floor; adjust the machine accordingly. This will be your starting position.','Push the handles together slowly as you squeeze your chest in the middle. Breathe out during this part of the motion and hold the contraction for a second.','Return back to the starting position slowly as you inhale until your chest muscles are fully stretched.','Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], null),
  ('barbell-incline-bench-press-medium-grip', 'Barbell Incline Bench Press - Medium Grip', 'chest', array['shoulders','triceps']::text[], 'barbell', array['Incline Bench Press','Incline Barbell Press']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Incline_Bench_Press_-_Medium_Grip/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Incline_Bench_Press_-_Medium_Grip/1.jpg', array['Lie back on an incline bench. Using a medium-width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.','As you breathe in, come down slowly until you feel the bar on you upper chest.','After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly again. Tip: it should take at least twice as long to go down than to come up.','Repeat the movement for the prescribed amount of repetitions.','When you are done, place the bar back in the rack.']::text[], '{}'::text[], null),
  ('decline-barbell-bench-press', 'Decline Barbell Bench Press', 'chest', array['shoulders','triceps']::text[], 'barbell', array['Decline Bench Press']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Barbell_Bench_Press/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Barbell_Bench_Press/1.jpg', array['Secure your legs at the end of the decline bench and slowly lay down on the bench.','Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. The arms should be perpendicular to the floor. This will be your starting position. Tip: In order to protect your rotator cuff, it is best if you have a spotter help you lift the barbell off the rack.','As you breathe in, come down slowly until you feel the bar on your lower chest.','After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up).','Repeat the movement for the prescribed amount of repetitions.','When you are done, place the bar back in the rack.']::text[], '{}'::text[], null),
  ('t-bar-row-with-handle', 'T-Bar Row with Handle', 'middle_back', array['biceps','lats']::text[], 'barbell', array['T-Bar Row','T Bar Row']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/T-Bar_Row_with_Handle/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/T-Bar_Row_with_Handle/1.jpg', array['Position a bar into a landmine or in a corner to keep it from moving. Load an appropriate weight onto your end.','Stand over the bar, and position a Double D row handle around the bar next to the collar. Using your hips and legs, rise to a standing position.','Assume a wide stance with your hips back and your chest up. Your arms should be extended. This will be your starting position.','Pull the weight to your upper abdomen by retracting the shoulder blades and flexing the elbows. Do not jerk the weight or cheat during the movement.','After a brief pause, return to the starting position.']::text[], '{}'::text[], null),
  ('rack-pulls', 'Rack Pulls', 'lower_back', array['forearms','glutes','hamstrings','traps']::text[], 'barbell', array['Rack Pull']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rack_Pulls/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rack_Pulls/1.jpg', array['Set up in a power rack with the bar on the pins. The pins should be set to the desired point; just below the knees, just above, or in the mid thigh position. Position yourself against the bar in proper deadlifting position. Your feet should be under your hips, your grip shoulder width, back arched, and hips back to engage the hamstrings. Since the weight is typically heavy, you may use a mixed grip, a hook grip, or use straps to aid in holding the weight.','With your head looking forward, extend through the hips and knees, pulling the weight up and back until lockout. Be sure to pull your shoulders back as you complete the movement.','Return the weight to the pins and repeat.']::text[], '{}'::text[], null),
  ('good-morning', 'Good Morning', 'hamstrings', array['abdominals','glutes','lower_back']::text[], 'barbell', array['Good Mornings']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Good_Morning/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Good_Morning/1.jpg', array['Begin with a bar on a rack at shoulder height. Rack the bar across the rear of your shoulders as you would a power squat, not on top of your shoulders. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Step back from the rack.','Begin by bending at the hips, moving them back as you bend over to near parallel. Keep your back arched and your cervical spine in proper alignment.','Reverse the motion by extending through the hips with your glutes and hamstrings. Continue until you have returned to the starting position.']::text[], '{}'::text[], null),
  ('barbell-glute-bridge', 'Barbell Glute Bridge', 'glutes', array['calves','hamstrings']::text[], 'barbell', array['Hip Thrust','Glute Bridge','Glute Bridges']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Glute_Bridge/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Glute_Bridge/1.jpg', array['Begin seated on the ground with a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise. Roll the bar so that it is directly above your hips, and lay down flat on the floor.','Begin the movement by driving through with your heels, extending your hips vertically through the bar. Your weight should be supported by your upper back and the heels of your feet.','Extend as far as possible, then reverse the motion to return to the starting position.']::text[], '{}'::text[], null),
  ('split-squat-with-dumbbells', 'Split Squat with Dumbbells', 'quadriceps', array['glutes','hamstrings']::text[], 'dumbbell', array['Dumbbell Split Squat']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Split_Squat_with_Dumbbells/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Split_Squat_with_Dumbbells/1.jpg', array['Position yourself into a staggered stance with the rear foot elevated and front foot forward.','Hold a dumbbell in each hand, letting them hang at the sides. This will be your starting position.','Begin by descending, flexing your knee and hip to lower your body down. Maintain good posture througout the movement. Keep the front knee in line with the foot as you perform the exercise.','At the bottom of the movement, drive through the heel to extend the knee and hip to return to the starting position.']::text[], '{}'::text[], null),
  ('dumbbell-lunges', 'Dumbbell Lunges', 'quadriceps', array['calves','glutes','hamstrings']::text[], 'dumbbell', array['Dumbbell Lunge','DB Lunge']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Lunges/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Lunges/1.jpg', array['Stand with your torso upright holding two dumbbells in your hands by your sides. This will be your starting position.','Step forward with your right leg around 2 feet or so from the foot being left stationary behind and lower your upper body down, while keeping the torso upright and maintaining balance. Inhale as you go down. Note: As in the other exercises, do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. Make sure that you keep your front shin perpendicular to the ground.','Using mainly the heel of your foot, push up and go back to the starting position as you exhale.','Repeat the movement for the recommended amount of repetitions and then perform with the left leg.']::text[], '{}'::text[], null),
  ('standing-leg-curl', 'Standing Leg Curl', 'hamstrings', '{}'::text[], 'machine', '{}'::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Leg_Curl/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Leg_Curl/1.jpg', array['Adjust the machine lever to fit your height and lie with your torso bent at the waist facing forward around 30-45 degrees (since an angled position is more favorable for hamstrings recruitment) with the pad of the lever on the back of your right leg (just a few inches under the calves) and the front of the right leg on top of the machine pad.','Keeping the torso bent forward, ensure your leg is fully stretched and grab the side handles of the machine. Position your toes straight. This will be your starting position.','As you exhale, curl your right leg up as far as possible without lifting the upper leg from the pad. Once you hit the fully contracted position, hold it for a second.','As you inhale, bring the legs back to the initial position. Repeat for the recommended amount of repetitions.','Perform the same exercise now for the left leg.']::text[], '{}'::text[], null),
  ('smith-machine-calf-raise', 'Smith Machine Calf Raise', 'calves', '{}'::text[], 'machine', '{}'::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Calf_Raise/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Calf_Raise/1.jpg', array['Place a block or weight plate below the bar on the Smith machine. Set the bar to a position that best matches your height. Once the correct height is chosen and the bar is loaded, step onto the plates with the balls of your feet and place the bar on the back of your shoulders.','Take the bar with both hands facing forward. Rotate the bar to unrack it. This will be your starting position.','Raise your heels as high as possible by pushing off of the balls of your feet, flexing your calf at the top of the contraction. Your knees should remain extended. Hold the contracted position for a second before you start to go back down.','Return slowly to the starting position as you breathe in while lowering your heels.','Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], null),
  ('donkey-calf-raises', 'Donkey Calf Raises', 'calves', '{}'::text[], 'other', array['Donkey Calf Raise']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Donkey_Calf_Raises/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Donkey_Calf_Raises/1.jpg', array['For this exercise you will need access to a donkey calf raise machine. Start by positioning your lower back and hips under the padded lever provided. The tailbone area should be the one making contact with the pad.','Place both of your arms on the side handles and place the balls of your feet on the calf block with the heels extending off. Align the toes forward, inward or outward, depending on the area you wish to target, and straighten the knees without locking them. This will be your starting position.','Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.','Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.','Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], null),
  ('crunches', 'Crunches', 'abdominals', '{}'::text[], 'body_only', array['Crunch']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Crunches/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Crunches/1.jpg', array['Lie flat on your back with your feet flat on the ground, or resting on a bench with your knees bent at a 90 degree angle. If you are resting your feet on a bench, place them three to four inches apart and point your toes inward so they touch.','Now place your hands lightly on either side of your head keeping your elbows in. Tip: Don''t lock your fingers behind your head.','While pushing the small of your back down in the floor to better isolate your abdominal muscles, begin to roll your shoulders off the floor.','Continue to push down as hard as you can with your lower back as you contract your abdominals and exhale. Your shoulders should come up off the floor only about four inches, and your lower back should remain on the floor. At the top of the movement, contract your abdominals hard and keep the contraction for a second. Tip: Focus on slow, controlled movement - don''t cheat yourself by using momentum.','After the one second contraction, begin to come down slowly again to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], null),
  ('plank', 'Plank', 'abdominals', '{}'::text[], 'body_only', array['Front Plank']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Plank/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Plank/1.jpg', array['Get into a prone position on the floor, supporting your weight on your toes and your forearms. Your arms are bent and directly below the shoulder.','Keep your body straight at all times, and hold this position as long as possible. To increase difficulty, an arm or leg can be raised.']::text[], '{}'::text[], null),
  ('russian-twist', 'Russian Twist', 'abdominals', array['lower_back']::text[], 'body_only', array['Russian Twists']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Russian_Twist/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Russian_Twist/1.jpg', array['Lie down on the floor placing your feet either under something that will not move or by having a partner hold them. Your legs should be bent at the knees.','Elevate your upper body so that it creates an imaginary V-shape with your thighs. Your arms should be fully extended in front of you perpendicular to your torso and with the hands clasped. This is the starting position.','Twist your torso to the right side until your arms are parallel with the floor while breathing out.','Hold the contraction for a second and move back to the starting position while breathing out. Now move to the opposite side performing the same techniques you applied to the right side.','Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], null),
  ('ab-roller', 'Ab Roller', 'abdominals', array['shoulders']::text[], 'other', array['Ab Wheel','Ab Wheel Rollout']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Ab_Roller/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Ab_Roller/1.jpg', array['Hold the Ab Roller with both hands and kneel on the floor.','Now place the ab roller on the floor in front of you so that you are on all your hands and knees (as in a kneeling push up position). This will be your starting position.','Slowly roll the ab roller straight forward, stretching your body into a straight position. Tip: Go down as far as you can without touching the floor with your body. Breathe in during this portion of the movement.','After a pause at the stretched position, start pulling yourself back to the starting position as you breathe out. Tip: Go slowly and keep your abs tight at all times.']::text[], '{}'::text[], null),
  ('wrist-roller', 'Wrist Roller', 'forearms', array['shoulders']::text[], 'other', '{}'::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wrist_Roller/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wrist_Roller/1.jpg', array['To begin, stand straight up grabbing a wrist roller using a pronated grip (palms facing down). Your feet should be shoulder width apart.','Slowly lift both arms until they are fully extended and parallel to the floor in front of you. Note: Make sure the rope is not wrapped around the roller. Your entire body should be stationary except for the forearms. This is the starting position.','Rotate one wrist at a time in an upward motion to bring the weight up to the bar by rolling the rope around the roller.','Once the weight has reached the bar, slowly begin to lower the weight back down by rotating the wrist in a downward motion until the weight reaches the starting position.','Repeat for the prescribed amount of repetitions in your program.']::text[], '{}'::text[], null),
  ('farmers-walk', 'Farmer''s Walk', 'forearms', array['abdominals','glutes','hamstrings','lower_back','quadriceps','traps']::text[], 'other', array['Farmers Walk','Farmer Walk']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Farmers_Walk/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Farmers_Walk/1.jpg', array['There are various implements that can be used for the farmers walk. These can also be performed with heavy dumbbells or short bars if these implements aren''t available. Begin by standing between the implements.','After gripping the handles, lift them up by driving through your heels, keeping your back straight and your head up.','Walk taking short, quick steps, and don''t forget to breathe. Move for a given distance, typically 50-100 feet, as fast as possible.']::text[], '{}'::text[], null),
  ('seated-dumbbell-press', 'Seated Dumbbell Press', 'shoulders', array['triceps']::text[], 'dumbbell', array['Seated DB Press']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Dumbbell_Press/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Dumbbell_Press/1.jpg', array['Grab a couple of dumbbells and sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs.','Clean the dumbbells up one at a time by using your thighs to bring the dumbbells up to shoulder height at each side.','Rotate the wrists so that the palms of your hands are facing forward. This is your starting position.','As you exhale, push the dumbbells up until they touch at the top.','After a second pause, slowly come down back to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], null),
  ('reverse-grip-triceps-pushdown', 'Reverse Grip Triceps Pushdown', 'triceps', '{}'::text[], 'cable', array['Reverse Grip Pushdown']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Grip_Triceps_Pushdown/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Grip_Triceps_Pushdown/1.jpg', array['Start by setting a bar attachment (straight or e-z) on a high pulley machine.','Facing the bar attachment, grab it with the palms facing up (supinated grip) at shoulder width. Lower the bar by using your lats until your arms are fully extended by your sides. Tip: Elbows should be in by your sides and your feet should be shoulder width apart from each other. This is the starting position.','Slowly elevate the bar attachment up as you inhale so it is aligned with your chest. Only the forearms should move and the elbows/upper arms should be stationary by your side at all times.','Then begin to lower the cable bar back down to the original staring position while exhaling and contracting the triceps hard.','Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], null),
  ('concentration-curls', 'Concentration Curls', 'biceps', array['forearms']::text[], 'dumbbell', array['Concentration Curl']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Concentration_Curls/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Concentration_Curls/1.jpg', array['Sit down on a flat bench with one dumbbell in front of you between your legs. Your legs should be spread with your knees bent and feet on the floor.','Use your right arm to pick the dumbbell up. Place the back of your right upper arm on the top of your inner right thigh. Rotate the palm of your hand until it is facing forward away from your thigh. Tip: Your arm should be extended and the dumbbell should be above the floor. This will be your starting position.','While holding the upper arm stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Tip: At the top of the movement make sure that the little finger of your arm is higher than your thumb. This guarantees a good contraction. Hold the contracted position for a second as you squeeze the biceps.','Slowly begin to bring the dumbbells back to starting position as your breathe in. Caution: Avoid swinging motions at any time.','Repeat for the recommended amount of repetitions. Then repeat the movement with the left arm.']::text[], '{}'::text[], null),
  ('barbell-rear-delt-row', 'Barbell Rear Delt Row', 'shoulders', array['biceps','lats','middle_back']::text[], 'barbell', array['Rear Delt Row']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Rear_Delt_Row/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Rear_Delt_Row/1.jpg', array['Stand up straight while holding a barbell using a wide (higher than shoulder width) and overhand (palms facing your body) grip.','Bend knees slightly and bend over as you keep the natural arch of your back. Let the arms hang in front of you as they hold the bar. Once your torso is parallel to the floor, flare the elbows out and away from your body. Tip: Your torso and your arms should resemble the letter "T". Now you are ready to begin the exercise.','While keeping the upper arms perpendicular to the torso, pull the barbell up towards your upper chest as you squeeze the rear delts and you breathe out. Tip: When performed correctly, this exercise should resemble a bench press in reverse. Also, refrain from using your biceps to do the work. Focus on targeting the rear delts; the arms should only act as hooks.','Slowly go back to the initial position as you breathe in.','Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], null),
  ('reverse-machine-flyes', 'Reverse Machine Flyes', 'shoulders', '{}'::text[], 'machine', array['Reverse Pec Deck','Rear Delt Fly']::text[], 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Machine_Flyes/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Machine_Flyes/1.jpg', array['Adjust the handles so that they are fully to the rear. Make an appropriate weight selection and adjust the seat height so the handles are at shoulder level. Grasp the handles with your hands facing inwards. This will be your starting position.','In a semicircular motion, pull your hands out to your side and back, contracting your rear delts.','Keep your arms slightly bent throughout the movement, with all of the motion occurring at the shoulder joint.','Pause at the rear of the movement, and slowly return the weight to the starting position.']::text[], '{}'::text[], null),
  ('bulgarian-split-squat', 'Bulgarian Split Squat', 'quadriceps', array['glutes','hamstrings']::text[], 'dumbbell', array['Rear Foot Elevated Split Squat','RFESS']::text[], null, null, array['Stand about a stride length in front of a bench with a dumbbell in each hand.','Place the top of your rear foot on the bench, keeping your front foot flat and pointed forward.','Lower until your front thigh is roughly parallel to the floor and your rear knee is just short of the ground.','Drive through the front heel to stand, keeping your torso tall throughout.']::text[], array['Keep your weight in the front heel — the back leg only balances.']::text[], 'Standing too close to the bench, which turns it into a knee-dominant quad crush and lets the front heel lift.')
on conflict (slug) do update set
  name = excluded.name,
  primary_muscle = excluded.primary_muscle,
  secondary_muscles = excluded.secondary_muscles,
  equipment = excluded.equipment,
  aliases = excluded.aliases,
  image_start_url = excluded.image_start_url,
  image_end_url = excluded.image_end_url,
  how_to = excluded.how_to,
  cues = excluded.cues,
  common_mistake = excluded.common_mistake;


-- ========================================================================
-- 20260905000004_sessions.sql
-- ========================================================================

-- JLIKA Gym — Phase 3: workout sessions and set logs.
-- Logged sets keep the load and reps as performed. Editing or republishing a
-- program never rewrites them, which is why set_logs carries its own
-- exercise_id rather than pointing at a program_exercises row.

create table if not exists public.workout_sessions (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users on delete cascade,
  -- Null when the program day is later deleted; the session survives.
  day_id uuid references public.program_days on delete set null,
  title text,
  started_at timestamptz not null default now(),
  ended_at timestamptz,
  bodyweight_kg numeric(5,2),
  notes text
);

create index if not exists workout_sessions_user_started_idx
  on public.workout_sessions (user_id, started_at desc);

-- At most one session in progress per person, so "resume" is never ambiguous.
create unique index if not exists workout_sessions_one_active_idx
  on public.workout_sessions (user_id) where ended_at is null;

alter table public.workout_sessions enable row level security;

drop policy if exists "workout_sessions: own rows" on public.workout_sessions;
create policy "workout_sessions: own rows"
  on public.workout_sessions for all
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

create table if not exists public.set_logs (
  id uuid primary key default gen_random_uuid(),
  session_id uuid not null references public.workout_sessions on delete cascade,
  exercise_id uuid not null references public.exercises,
  set_index int not null check (set_index >= 0),
  weight_kg numeric(6,2) check (weight_kg >= 0),
  reps int check (reps >= 0),
  rpe numeric(3,1) check (rpe >= 1 and rpe <= 10),
  is_complete boolean not null default false,
  logged_at timestamptz not null default now(),
  unique (session_id, exercise_id, set_index)
);

create index if not exists set_logs_session_idx on public.set_logs (session_id);
-- Drives "your history" and the progression hint for one movement.
create index if not exists set_logs_exercise_idx
  on public.set_logs (exercise_id, logged_at desc) where is_complete;

alter table public.set_logs enable row level security;

drop policy if exists "set_logs: through session" on public.set_logs;
create policy "set_logs: through session"
  on public.set_logs for all
  using (exists (
    select 1 from public.workout_sessions s
    where s.id = session_id and s.user_id = (select auth.uid())
  ))
  with check (exists (
    select 1 from public.workout_sessions s
    where s.id = session_id and s.user_id = (select auth.uid())
  ));


-- ========================================================================
-- 20260905000005_body.sql
-- ========================================================================

-- JLIKA Gym — Phase 4: body metrics and progress photos.
-- Photos are private. The bucket is not public and the app hands out short-lived
-- signed URLs generated server-side; there is no second PIN on top.

create table if not exists public.body_metrics (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users on delete cascade,
  -- A date, never a timestamp: a weigh-in belongs to a day, not an instant.
  measured_on date not null,
  weight_kg numeric(5,2) check (weight_kg > 0 and weight_kg < 400),
  waist_cm numeric(5,1) check (waist_cm > 0),
  chest_cm numeric(5,1) check (chest_cm > 0),
  arm_cm numeric(5,1) check (arm_cm > 0),
  thigh_cm numeric(5,1) check (thigh_cm > 0),
  hip_cm numeric(5,1) check (hip_cm > 0),
  bodyfat_pct numeric(4,1) check (bodyfat_pct > 0 and bodyfat_pct < 80),
  note text,
  created_at timestamptz not null default now(),
  unique (user_id, measured_on)
);

create index if not exists body_metrics_user_date_idx
  on public.body_metrics (user_id, measured_on desc);

alter table public.body_metrics enable row level security;

drop policy if exists "body_metrics: own rows" on public.body_metrics;
create policy "body_metrics: own rows"
  on public.body_metrics for all
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

create table if not exists public.progress_photos (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users on delete cascade,
  taken_on date not null,
  pose text not null check (pose in ('front','side','back')),
  -- Always {user_id}/{uuid}.webp — the storage policy keys on the first segment.
  storage_path text not null unique,
  weight_kg numeric(5,2),
  created_at timestamptz not null default now()
);

create index if not exists progress_photos_user_date_idx
  on public.progress_photos (user_id, taken_on desc);

alter table public.progress_photos enable row level security;

drop policy if exists "progress_photos: own rows" on public.progress_photos;
create policy "progress_photos: own rows"
  on public.progress_photos for all
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

-- ------------------------------------------------------------------ storage

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('progress-photos', 'progress-photos', false, 8388608, array['image/webp','image/jpeg','image/png'])
on conflict (id) do update set
  public = false,
  file_size_limit = 8388608,
  allowed_mime_types = array['image/webp','image/jpeg','image/png'];

-- Each person can only touch objects under a folder named after their own uid.
drop policy if exists "progress photos are private to their owner" on storage.objects;
create policy "progress photos are private to their owner"
  on storage.objects for all
  using (
    bucket_id = 'progress-photos'
    and (storage.foldername(name))[1] = (select auth.uid())::text
  )
  with check (
    bucket_id = 'progress-photos'
    and (storage.foldername(name))[1] = (select auth.uid())::text
  );


-- ========================================================================
-- 20260905000006_nutrition.sql
-- ========================================================================

-- JLIKA Gym — Phase 5: ingredients, recipes, meal plans and the grocery list.
-- Allergies and excluded ingredients are hard filters: a recipe containing one
-- must never appear in a plan, a swap or a search result.

create table if not exists public.ingredients (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid references auth.users on delete cascade,  -- null = global seed
  slug text unique not null,
  name text not null,
  category text not null check (category in (
    'protein','carbs','produce','dairy','fats','pantry','other'
  )),
  kcal_per_100g numeric(6,1) not null check (kcal_per_100g >= 0),
  protein_g numeric(5,1) not null default 0,
  carb_g numeric(5,1) not null default 0,
  fat_g numeric(5,1) not null default 0,
  -- Matched against user_excludes of kind 'allergen'.
  allergens text[] not null default '{}',
  -- How the grocery list should read: '250 g' vs '3'.
  unit_hint text not null default 'g'
);

alter table public.ingredients enable row level security;

drop policy if exists "ingredients: read global or own" on public.ingredients;
create policy "ingredients: read global or own"
  on public.ingredients for select
  using (owner_id is null or owner_id = (select auth.uid()));

drop policy if exists "ingredients: write own" on public.ingredients;
create policy "ingredients: write own"
  on public.ingredients for all
  using (owner_id = (select auth.uid()))
  with check (owner_id = (select auth.uid()));

create table if not exists public.recipes (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid references auth.users on delete cascade,
  slug text unique not null,
  name text not null,
  slot_hint text check (slot_hint in ('breakfast','lunch','pre_workout','dinner','snack')),
  prep_minutes int check (prep_minutes >= 0),
  image_url text,
  steps text[] not null default '{}'
);

alter table public.recipes enable row level security;

drop policy if exists "recipes: read global or own" on public.recipes;
create policy "recipes: read global or own"
  on public.recipes for select
  using (owner_id is null or owner_id = (select auth.uid()));

drop policy if exists "recipes: write own" on public.recipes;
create policy "recipes: write own"
  on public.recipes for all
  using (owner_id = (select auth.uid()))
  with check (owner_id = (select auth.uid()));

create table if not exists public.recipe_ingredients (
  recipe_id uuid not null references public.recipes on delete cascade,
  ingredient_id uuid not null references public.ingredients,
  grams numeric(7,1) not null check (grams > 0),
  primary key (recipe_id, ingredient_id)
);

alter table public.recipe_ingredients enable row level security;

-- Readable when the parent recipe is readable; writable only for your own.
drop policy if exists "recipe_ingredients: read through recipe" on public.recipe_ingredients;
create policy "recipe_ingredients: read through recipe"
  on public.recipe_ingredients for select
  using (exists (
    select 1 from public.recipes r
    where r.id = recipe_id and (r.owner_id is null or r.owner_id = (select auth.uid()))
  ));

drop policy if exists "recipe_ingredients: write through own recipe" on public.recipe_ingredients;
create policy "recipe_ingredients: write through own recipe"
  on public.recipe_ingredients for all
  using (exists (
    select 1 from public.recipes r where r.id = recipe_id and r.owner_id = (select auth.uid())
  ))
  with check (exists (
    select 1 from public.recipes r where r.id = recipe_id and r.owner_id = (select auth.uid())
  ));

create table if not exists public.meal_plans (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users on delete cascade,
  week_start date not null,
  created_at timestamptz not null default now(),
  unique (user_id, week_start)
);

alter table public.meal_plans enable row level security;

drop policy if exists "meal_plans: own rows" on public.meal_plans;
create policy "meal_plans: own rows"
  on public.meal_plans for all
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

create table if not exists public.meal_plan_entries (
  id uuid primary key default gen_random_uuid(),
  plan_id uuid not null references public.meal_plans on delete cascade,
  planned_on date not null,
  slot text not null check (slot in ('breakfast','lunch','pre_workout','dinner','snack')),
  recipe_id uuid references public.recipes on delete set null,
  servings numeric(4,2) not null default 1 check (servings > 0),
  eaten boolean not null default false,
  unique (plan_id, planned_on, slot)
);

create index if not exists meal_plan_entries_plan_date_idx
  on public.meal_plan_entries (plan_id, planned_on);

alter table public.meal_plan_entries enable row level security;

drop policy if exists "meal_plan_entries: through plan" on public.meal_plan_entries;
create policy "meal_plan_entries: through plan"
  on public.meal_plan_entries for all
  using (exists (
    select 1 from public.meal_plans p where p.id = plan_id and p.user_id = (select auth.uid())
  ))
  with check (exists (
    select 1 from public.meal_plans p where p.id = plan_id and p.user_id = (select auth.uid())
  ));

create table if not exists public.grocery_items (
  id uuid primary key default gen_random_uuid(),
  plan_id uuid not null references public.meal_plans on delete cascade,
  ingredient_id uuid not null references public.ingredients,
  total_grams numeric(8,1) not null check (total_grams > 0),
  checked boolean not null default false,
  unique (plan_id, ingredient_id)
);

alter table public.grocery_items enable row level security;

drop policy if exists "grocery_items: through plan" on public.grocery_items;
create policy "grocery_items: through plan"
  on public.grocery_items for all
  using (exists (
    select 1 from public.meal_plans p where p.id = plan_id and p.user_id = (select auth.uid())
  ))
  with check (exists (
    select 1 from public.meal_plans p where p.id = plan_id and p.user_id = (select auth.uid())
  ));

create table if not exists public.user_excludes (
  user_id uuid not null references auth.users on delete cascade,
  kind text not null check (kind in ('allergen','ingredient','preference')),
  value text not null,
  primary key (user_id, kind, value)
);

alter table public.user_excludes enable row level security;

drop policy if exists "user_excludes: own rows" on public.user_excludes;
create policy "user_excludes: own rows"
  on public.user_excludes for all
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));


